function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{const n=el.dataset.icon;el.innerHTML=icon(el.closest('.transport,.full-controls')&&referenceIcons['player-'+n]?'player-'+n:n);});root.querySelectorAll('img').forEach(el=>{el.addEventListener('error',()=>{if(el.closest('.song-credit-avatar')){el.remove();return;}el.src=el.closest('.artist-list-item')?artistPlaceholder:placeholder(el.alt||'Musik');},{once:true});});}
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function api(endpoint,params={}){const r=await fetch('/api/'+endpoint+'?'+new URLSearchParams(params));const data=await r.json();if(!r.ok){if(r.status===401&&!login.open)login.showModal();throw Error(data.error||'Anfrage fehlgeschlagen.');}return data;}
const current=()=>state.queue[state.index];
const mobileNavigation=matchMedia('(max-width:483px)');
function setMobileNavigation(open){const mobile=mobileNavigation.matches,wasOpen=document.body.classList.contains('nav-open');open=mobile&&open;document.body.classList.toggle('nav-open',open);$('.sidebar').inert=mobile&&!open;main.inert=mobile&&open;$('#player').inert=mobile&&open;$('#mobile-nav').setAttribute('aria-label',open?'Navigation schließen':'Navigation öffnen');$('#mobile-nav').setAttribute('aria-expanded',String(open));$('#mobile-nav').setAttribute('aria-controls','sidebar');if(wasOpen&&!open&&mobile)$('#mobile-nav').focus({preventScroll:true});}
mobileNavigation.addEventListener('change',()=>setMobileNavigation(false));
let resizeVisualTimer;
window.addEventListener('resize',()=>{document.documentElement.classList.add('viewport-resizing');clearTimeout(resizeVisualTimer);resizeVisualTimer=setTimeout(()=>document.documentElement.classList.remove('viewport-resizing'),180);});
function navigate(route){rememberSearchView();rememberNewView();setMobileNavigation(false);location.hash='#/'+route;}
async function reloadPlaylists(){const user=state.user,scope=state.accountEpoch,data=await api('getPlaylists');if(state.user!==user||state.accountEpoch!==scope)return;state.playlists=data.playlists?.playlist||[];navigation();}
const scrobbleTracker=new ScrobbleTracker({report:payload=>{
 const epoch=state.accountEpoch,user=state.user;if(!user)return;
 fetch('/api/scrobble',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(10000)}).then(async response=>{
  if(!response.ok)throw Error('Wiedergabeverlauf konnte nicht gespeichert werden.');
  if(payload.submission&&state.accountEpoch===epoch&&state.user===user&&state.route==='home'){
   const y=window.scrollY,top=main.scrollTop;await render();if(state.accountEpoch===epoch&&state.user===user&&state.route==='home'){main.scrollTop=top;window.scrollTo(0,y);}
  }
 }).catch(()=>{if(payload.submission&&state.accountEpoch===epoch&&state.user===user)toast('Wiedergabeverlauf konnte nicht gespeichert werden.');});
}});
const recentSearches=new RecentSearches(localStorage);
const libraryNavigation=new LibraryNavigation(localStorage);
let navigationEditing=false;
const mobileSearch=new MobileSearchInteraction();
const recentKindLabel={artist:'Künstler:in',album:'Album',playlist:'Playlist'};
function recordRecentRoute(route){
 if(state.route!=='search'||!state.user)return;
 const target=readRoute(route.startsWith('#')?route:'#/'+route),kind=target.route.split('/')[0];if(!Object.hasOwn(recentKindLabel,kind)||!target.id)return;
 const results=searchCache.get(readRoute(location.hash).term)||{};
 let item=(kind==='playlist'?matchingPlaylists(state.playlists,readRoute(location.hash).term):results[kind]||[]).find(item=>item.id===target.id)||recentSearches.list().find(item=>item.kind===kind&&item.id===target.id);
 if(!item&&kind==='album'){const song=state.viewSongs.find(song=>song.albumId===target.id);if(song)item={id:song.albumId,name:song.album,coverArt:song.coverArt};}
 if(!item&&kind==='artist'){for(const song of state.viewSongs){item=song.artists?.find(artist=>artist.id===target.id);if(item)break;if(song.artistId===target.id){item={id:song.artistId,name:song.artist};break;}}}
 if(item)recentSearches.remember(kind,item);
}
function mobileSearchMarkup(){
 const entries=recentSearches.list();if(!entries.length)return '';
 return '<section class="search-mobile-recents" aria-label="Zuletzt gesucht"><div class="search-recents-heading"><h2>Zuletzt gesucht</h2><button data-clear-search-recents>Löschen</button></div><ul id="search-suggestions" role="listbox" aria-label="Vorschläge">'+entries.map((item,index)=>{const route=item.kind+'/'+encodeURIComponent(item.id),image=item.kind==='artist'&&!item.coverArt?artistPlaceholder:cover(item,112);return '<li role="option" tabindex="0" id="search-suggestion-'+index+'" data-recent-route="'+esc(route)+'"><img class="'+(item.kind==='artist'?'artist-image':'')+'" src="'+esc(image)+'" alt=""><div><a href="#/'+esc(route)+'">'+esc(item.name)+'</a><a class="search-recent-type" href="#/'+esc(route)+'">'+recentKindLabel[item.kind]+'</a></div>'+'<svg xmlns="http://www.w3.org/2000/svg" width="36" height="64" viewBox="0 0 36 64" aria-hidden="true"><path d="M3.344 64c.957 0 1.768-.368 2.394-.994l29.2-28.538c.701-.7 1.069-1.547 1.069-2.468 0-.957-.368-1.841-1.068-2.467L5.774 1.031C5.112.37 4.301.001 3.344.001 1.43 0-.006 1.472-.006 3.387c0 .884.367 1.767.956 2.393L27.758 32 .95 58.218a3.5 3.5 0 0 0-.956 2.395c0 1.914 1.435 3.387 3.35 3.387"/></svg>'+'</li>';}).join('')+'</ul></section>';
}
function syncMobileSearchUI({repaint=false}={}){
 const field=$('#search'),holder=$('#mobile-search-recents');if(!field||!holder)return;
 if(repaint){holder.innerHTML=mobileSearchMarkup();hydrate(holder);}
 const active=mobileNavigation.matches&&mobileSearch.active,preview=active&&mobileSearch.preview;
 main.classList.toggle('search-mobile-active',active);main.classList.toggle('search-mobile-history',preview);
 if(active)field.setAttribute('aria-autocomplete','list');else field.removeAttribute('aria-autocomplete');if(preview&&holder.querySelector('#search-suggestions'))field.setAttribute('aria-controls','search-suggestions');else field.removeAttribute('aria-controls');
 const rows=[...holder.querySelectorAll('[role=option]')];
 for(const [index,row] of rows.entries())row.classList.toggle('search-suggestion-active',preview&&index===mobileSearch.index);
 const selected=preview&&rows[mobileSearch.index];if(selected){field.setAttribute('aria-activedescendant',selected.id);selected.scrollIntoView({block:'nearest'});}else field.removeAttribute('aria-activedescendant');
}
function openMobileRecent(index){const item=recentSearches.list()[index];if(!item)return;const route=item.kind+'/'+encodeURIComponent(item.id);recordRecentRoute(route);navigate(route);}
document.addEventListener('focusin',event=>{if(event.target.id==='search'&&mobileNavigation.matches){mobileSearch.focus(event.target.value,readRoute(location.hash).term);syncMobileSearchUI();}});
document.addEventListener('input',event=>{if(event.target.id==='search'&&mobileNavigation.matches){mobileSearch.edit();syncMobileSearchUI();}});
document.addEventListener('click',event=>{
 if(event.target.closest('[data-search-cancel]')){const field=$('#search');if(field){field.value=mobileSearch.cancel();retainedSearchDraft='';field.blur();}event.target.closest('button')?.blur();syncMobileSearchUI();return;}
 const row=event.target.closest('[data-recent-route]');if(row&&!event.target.closest('a')){const route=row.dataset.recentRoute;recordRecentRoute(route);navigate(route);}
});
document.addEventListener('keydown',event=>{
 if(!mobileNavigation.matches||!main.classList.contains('search-page'))return;
 const row=event.target.closest('[data-recent-route]');if(row&&['Enter',' '].includes(event.key)){event.preventDefault();event.stopImmediatePropagation();recordRecentRoute(row.dataset.recentRoute);navigate(row.dataset.recentRoute);return;}
 if(event.target.id!=='search'||event.isComposing||!mobileSearch.active)return;
 if(event.key==='Escape'){mobileSearch.index=-1;syncMobileSearchUI();event.preventDefault();event.stopImmediatePropagation();return;}
 if(!mobileSearch.preview)return;
 if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();mobileSearch.move(event.key==='ArrowDown'?1:-1,recentSearches.list().length);syncMobileSearchUI();return;}
 if(event.key==='Enter'&&mobileSearch.index>=0){event.preventDefault();openMobileRecent(mobileSearch.index);}
});
function searchStartMarkup(){
 const entries=recentSearches.list();
 const recent=entries.length?'<section class="search-recents" aria-label="Zuletzt gesucht"><div class="search-recents-heading"><h2>Zuletzt gesucht</h2><button data-clear-search-recents>Löschen</button></div><ul class="search-recents-grid">'+entries.map((item,index)=>{const route=item.kind+'/'+encodeURIComponent(item.id),image=item.kind==='artist'&&!item.coverArt?artistPlaceholder:cover(item,84);return '<li class="search-recent '+(item.kind==='artist'?'search-recent-artist':'')+'"><a class="search-recent-open" href="#/'+route+'" aria-label="'+esc(item.name+' · '+recentKindLabel[item.kind])+'"></a><div class="search-recent-content"><img src="'+esc(image)+'" alt=""><div><strong>'+esc(item.name)+'</strong><small>'+recentKindLabel[item.kind]+'</small><span>AUS DEINER MEDIATHEK</span></div></div><button class="search-recent-menu" '+(item.kind==='artist'?'data-recent-artist="'+index+'"':'data-card-menu="'+route+'"')+' aria-label="Aktionen für '+esc(item.name)+'">'+icon('more')+'</button></li>';}).join('')+'</ul></section>':'';
 return '<div class="search-start">'+recent+'<div class="search-empty" role="status"><div class="search-empty-icon">'+icon('search-empty')+'</div><p>In Mediathek suchen</p></div></div>';
}
document.addEventListener('click',event=>{const target=event.target.closest('a[href^="#/"],[data-open]');if(target&&main.contains(target))recordRecentRoute(target.dataset.open||target.getAttribute('href'));},{capture:true});
const sharing=new MediaSharing({navigator,getBase:()=>location.href});
function mediaShareButtons(attribute){return (sharing.nativeAvailable?`<button role="menuitem" ${attribute}="share">${icon('share')}Teilen</button>`:'')+`<button role="menuitem" ${attribute}="link">${icon('link')}Link kopieren</button>`;}
async function performMediaShare(action,kind,item){const epoch=state.accountEpoch;playlistActions.close();try{const result=await sharing[action==='share'?'share':'copy'](kind,item);if(state.accountEpoch===epoch&&result.action==='copied')toast('Link kopiert.');}catch{if(state.accountEpoch===epoch)toast(action==='share'?'Teilen ist gerade nicht möglich.':'Der Link konnte nicht kopiert werden.');}}
const playlistActions=new PlaylistActions({getPlaylists:()=>state.playlists,getUser:()=>state.user,getScope:()=>state.accountEpoch,refresh:reloadPlaylists,toast,saved:async(result,id,created,operation)=>{const savedUser=state.user,savedScope=state.accountEpoch;if(operation==='delete'){state.playlists=state.playlists.filter(item=>item.id!==id);recentSearches.remove('playlist',id);navigation();}await reloadPlaylists();if(state.user!==savedUser||state.accountEpoch!==savedScope)return;state.libraryCache.delete('discover/new');if(operation==='delete'){recentSearches.remove('playlist',id);if(state.route==='playlist/'+encodeURIComponent(id)){navigate('playlists');main.focus({preventScroll:true});return;}await render();main.focus({preventScroll:true});return;}if(created&&id)navigate('playlist/'+encodeURIComponent(id));else if(operation==='edit'||id&&state.route==='playlist/'+encodeURIComponent(id)){rememberSearchView();const route=state.route,y=window.scrollY,top=main.scrollTop,libraryTop=main.querySelector('.library-scroll')?.scrollTop,generation=state.generation+1;await render();if(state.accountEpoch===savedScope&&state.route===route&&state.generation===generation){main.scrollTop=top;const scroll=main.querySelector('.library-scroll');if(scroll&&libraryTop!==undefined)scroll.scrollTop=libraryTop;window.scrollTo(0,y);}}}});
const tableSelection=new TableSelection(main,{getSongs:table=>table.classList.contains('library-tracks')?(state.libraryCache.get('songs')?.all||state.viewSongs):state.viewSongs,play:playList});
function playlistReorderContext(){const item=state.collection;if(item?.kind!=='playlist'||state.route!=='playlist/'+encodeURIComponent(item.id)||typeof item.owner!=='string'||item.owner.toLocaleLowerCase()!==state.user?.toLocaleLowerCase())return null;return {id:item.id,name:item.name||'',changed:item.changed||'',scope:state.accountEpoch,songIds:state.viewSongs.map(song=>song.id)};}
const playlistReorder=new PlaylistReorder(main,{context:playlistReorderContext,selection:tableSelection,save:savePlaylistOrder,failed:(error,drag)=>{if(drag.scope===state.accountEpoch)toast(error.message);}});
async function savePlaylistOrder(drag){
 const route='playlist/'+encodeURIComponent(drag.id),top=main.scrollTop;
 const response=await fetch('/api/playlist/reorder',{method:'POST',headers:{'Content-Type':'application/json'},signal:AbortSignal.timeout(25000),body:JSON.stringify({playlistId:drag.id,expectedName:drag.name,expectedChanged:drag.changed,expectedSongIds:drag.songIds,order:drag.order})}),result=await response.json();
 if(drag.scope!==state.accountEpoch)return;if(!response.ok)throw Error(result.error||'Reihenfolge konnte nicht gespeichert werden.');
 try{await playlistActions.saved(result,drag.id,false,'reorder');}catch{if(drag.scope===state.accountEpoch)toast('Reihenfolge gespeichert. Bitte neu laden.');return;}
 if(drag.scope!==state.accountEpoch)return;
 if(state.route===route&&state.viewSongs.length===drag.order.length&&drag.order.every((index,i)=>state.viewSongs[i].id===drag.songIds[index])){
  const table=main.querySelector('.song-table'),selection=tableSelection.state(table);selection.indices=new Set(drag.indices.map(index=>drag.order.indexOf(index)));selection.anchor=Math.min(...selection.indices);tableSelection.sync(table);main.scrollTop=top;table.querySelector('[data-row-index="'+selection.anchor+'"]')?.focus({preventScroll:true});
 }
 toast('Reihenfolge gespeichert.');
}

const navigationStops=new Map();
let navigationStopAccount;
const navigationGroup=route=>['search','home','new'].includes(route)?'main':['recent','artists','albums','songs'].includes(route)?'library':'playlists';
function syncNavigationStops(){
 if(navigationStopAccount!==state.accountEpoch){navigationStops.clear();navigationStopAccount=state.accountEpoch;}
 const items=$$('.sidebar-scroll .nav[data-view]');
 for(const group of ['main','library','playlists']){
  const members=items.filter(item=>navigationGroup(item.dataset.view)===group);
  const stop=members.find(item=>item.dataset.view===navigationStops.get(group))||members.find(item=>item.classList.contains('active'))||members[0];
  if(stop)navigationStops.set(group,stop.dataset.view);
  for(const item of members)item.tabIndex=item===stop?0:-1;
 }
}
$('.sidebar-scroll').addEventListener('focusin',event=>{
 const item=event.target.closest('.nav[data-view]');if(!item)return;
 navigationStops.set(navigationGroup(item.dataset.view),item.dataset.view);syncNavigationStops();
});
$('.sidebar-scroll').addEventListener('keydown',event=>{
 const item=event.target.closest('.nav[data-view]');
 if(!item||event.isComposing||event.altKey||event.ctrlKey||event.metaKey||!['ArrowUp','ArrowDown'].includes(event.key))return;
 const items=$$('.sidebar-scroll .nav[data-view]').filter(item=>!item.disabled),index=items.indexOf(item);
 if(index<0)return;event.preventDefault();items[Math.max(0,Math.min(items.length-1,index+(event.key==='ArrowDown'?1:-1)))].focus();
});
const libraryNavigationItems=[['Zuletzt hinzugefügt','recent','clock'],['Künstler','artists','artist'],['Alben','albums','album'],['Titel','songs','note']];
function navigation(){const focusedRoute=document.activeElement?.closest('.sidebar-scroll .nav[data-view]')?.dataset.view;const nav=(name,id,i)=>'<button class="nav '+((state.route===id||id==='artists'&&state.route.startsWith('artist/'))?'active':'')+'" data-view="'+id+'" '+((state.route===id||id==='artists'&&state.route.startsWith('artist/'))?'aria-current="page"':'')+'>'+icon(i)+'<span class="nav-label">'+esc(name)+'</span></button>';const library=libraryNavigationItems.filter(([,id])=>navigationEditing||libraryNavigation.visible(id)).map(([name,id,i])=>navigationEditing?'<label class="nav nav-edit-row"><input type="checkbox" data-library-visibility="'+id+'" '+(libraryNavigation.visible(id)?'checked':'')+'><span class="nav-edit-icon">'+icon(i)+'</span><span class="nav-label">'+esc(name)+'</span></label>':nav(name,id,i)).join('');$('#navigation').innerHTML=nav('Startseite','home','home')+nav('Neu','new','new')+'<div class="nav-group library-nav-heading"><span>Mediathek</span><button data-library-edit aria-expanded="'+navigationEditing+'" aria-controls="library-navigation-items">'+(navigationEditing?'Fertig':'Bearbeiten')+'</button></div><div id="library-navigation-items" role="group" aria-label="Mediathek">'+library+'</div><div class="nav-group"><span>Playlists</span></div>'+nav('Alle Playlists','playlists','new')+nav('Lieblingstitel','favorites','star')+state.playlists.map(p=>nav(p.name,'playlist/'+encodeURIComponent(p.id),'playlist')).join('');$('.search-nav').classList.toggle('active',state.route==='search');syncNavigationStops();if(focusedRoute){const focused=$$('.sidebar-scroll .nav[data-view]').find(item=>item.dataset.view===focusedRoute);focused?.focus({preventScroll:true});}}
$('#navigation').addEventListener('click',event=>{if(!event.target.closest('[data-library-edit]'))return;navigationEditing=!navigationEditing;navigation();$('#navigation [data-library-edit]').focus({preventScroll:true});});
$('#navigation').addEventListener('change',event=>{if(event.target.matches('[data-library-visibility]'))libraryNavigation.setVisible(event.target.dataset.libraryVisibility,event.target.checked);});
function favoriteButton(item,kind='song',extra=''){const selected=state.favorites[kind].has(item.id);return `<button class="favorite-toggle ${extra} ${selected?'is-favorite':''}" data-favorite-id="${esc(item.id)}" data-favorite-kind="${kind}" data-favorite-title="${esc(item.title||item.name)}" aria-pressed="${selected}" aria-label="${selected?'Favorit entfernen':'Als Favorit markieren'}: ${esc(item.title||item.name)}" title="${selected?'Favorit entfernen':'Als Favorit markieren'}">${icon(selected?(extra.includes('row-favorite')?'favorite-selected':'favorite-full-selected'):(extra.includes('row-favorite')?'favorite-row':'favorite'))}</button>`;}
function refreshFavorites(){for(const b of $$('[data-favorite-id]')){const selected=state.favorites[b.dataset.favoriteKind||'song'].has(b.dataset.favoriteId);b.classList.toggle('is-favorite',selected);const compact=b.classList.contains('row-favorite')||b.classList.contains('mini-favorite');b.innerHTML=icon(selected?(compact?'favorite-selected':'favorite-full-selected'):(compact?'favorite-row':'favorite'));b.setAttribute('aria-pressed',String(selected));b.title=selected?'Favorit entfernen':'Als Favorit markieren';b.setAttribute('aria-label',b.title+(b.dataset.favoriteTitle?': '+b.dataset.favoriteTitle:''));}refreshArtistCardBadges();}
async function toggleFavorite(id,kind='song',button){if(button?.disabled)return;const epoch=state.accountEpoch,selected=!state.favorites[kind].has(id);if(button)button.disabled=true;try{const response=await fetch('/api/favorite',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,kind,starred:selected})});const result=await response.json();if(epoch!==state.accountEpoch)return;if(!response.ok)throw Error(result.error||'Favorit konnte nicht gespeichert werden.');if(result.starred)state.favorites[kind].add(id);else state.favorites[kind].delete(id);refreshFavorites();if(kind==='artist'&&$('#artist-list')){$('#artist-list').innerHTML=artistList(state.selectedArtist);hydrate($('#artist-list'));}if(state.route==='favorites'&&kind==='song')await render();}catch(error){if(epoch===state.accountEpoch)toast(error.message);}finally{if(button)button.disabled=false;}}
function empty(title,subtitle=''){return `<div class="empty">${icon('note')}<h2>${esc(title)}</h2><p>${esc(subtitle)}</p></div>`;}
const collectionRoute=(item,kind)=>item.isFavorites?'favorites':kind+'/'+encodeURIComponent(item.id);
function cards(albums,kind='album',shelf=false,showYear=false){return `<div class="album-grid ${shelf?'album-shelf':''}">${albums.map(a=>`<article class="card ${kind==='artist'?'artist-card':''}"><div class="cover-art"><button class="cover-button" data-open="${collectionRoute(a,kind)}" aria-label="${esc(a.name||a.title)} öffnen"><img src="${esc(cover(a))}" ${favoritesArtworkAttributes(a)} alt="${esc(a.name||a.title)}" loading="lazy"></button>${kind!=='artist'?`<button class="cover-play" data-collection-play="${collectionRoute(a,kind)}" aria-label="${esc(a.name||a.title)} wiedergeben">${icon('play')}</button><button class="cover-more" data-card-menu="${collectionRoute(a,kind)}" aria-label="Aktionen für ${esc(a.name||a.title)}">${icon('more')}</button>`:''}</div><div class="card-meta"><button class="card-name" data-open="${collectionRoute(a,kind)}">${kind==='artist'?artistCardName(a):esc(a.name||a.title)+explicitBadge(a)}${a.isFavorites?`<span class="title-favorite-badge" aria-label="Favorit">${icon('favorite-selected')}</span>`:''}</button><p class="card-sub">${esc(showYear?(a.year||''):a.artist|| (kind==='playlist'?playlistCardOwner(a,state.user):kind==='artist'?`${a.albumCount||0} Alben`:''))}</p></div></article>`).join('')}</div>`;}
