function explicitBadge(item,variant='standard'){if(item?.explicitStatus!=='explicit')return '';const player=variant!=='standard';return (player?'':' ')+'<span class="explicit-badge'+(player?' player-explicit':'')+'" role="img" aria-label="'+(player?'Anstößiger Inhalt':'Nicht jugendfrei (explicit)')+'">'+explicitIcons[variant==='full-player'?'full':'standard']+'</span>';}

function table(songs,detail=false,library=false){state.viewSongs=songs;const isAlbum=detail&&state.route.startsWith('album/'),reorder=detail&&!!playlistReorderContext();return songs.length?`<table ${reorder?'data-reorder-playlist="true"':''} role="grid" aria-label="Titelliste" aria-multiselectable="true" class="song-table ${isAlbum?'album-tracks':'playlist-tracks'} ${library?'library-tracks':''}">${isAlbum?'<colgroup><col><col class="duration"><col class="menu-cell"></colgroup>':'<colgroup><col class="playlist-title-col"><col class="artist-col"><col class="album-col"><col class="duration"><col class="menu-cell"></colgroup>'}<thead><tr><th class="song-title-cell">${library?'Name':'Titel'}</th>${isAlbum?'':`<th class="artist-col">${library?'Künstler':'Künstler:in'}</th><th class="album-col">Album</th>`}<th class="duration">Länge</th><th class="menu-cell"></th></tr></thead><tbody>${songs.map((s,i)=>`<tr class="${current()?.id===s.id?'current':''}" ${reorder?'draggable="true"':''} data-song-id="${esc(s.id)}" data-row-index="${i}" tabindex="0" aria-selected="false"><td>${favoriteButton(s,'song','row-favorite')}<div class="song-cell">${isAlbum?`<button class="index song-play" data-play="${i}" aria-label="${esc(s.title)} wiedergeben"><span class="track-number">${s.track||i+1}</span><span class="track-hover">${icon('play')}</span></button>`:`<button class="song-art song-play" data-play="${i}" aria-label="${esc(s.title)} wiedergeben"><img src="${esc(cover(s,80))}" alt=""><span class="song-art-play">${icon('play')}</span></button>`}<span class="song-label"><strong><a class="song-title-link" href="#/song/${encodeURIComponent(s.id)}"><span class="song-name-text">${esc(s.title)}</span></a>${explicitBadge(s)}</strong>${!isAlbum||albumSongHasByline(s,state.collection)?`<small>${renderSongArtists(s)}</small>`:''}</span></div></td>${isAlbum?'':`<td class="artist-col">${renderSongArtists(s)}</td><td class="album-col">${renderSongAlbum(s)}</td>`}<td class="duration">${time(s.duration)}</td><td class="menu-cell"><button data-menu="${i}" aria-label="Aktionen für ${esc(s.title)}">${icon('more')}</button></td></tr>`).join('')}</tbody></table>`:empty('Noch keine Titel','Hier erscheinen die Titel aus deiner Mediathek.');}
