function openSongLyrics(anchor){
 const page=state.songPage;if(!page?.lines.length)return;const dialog=$('#description-dialog');descriptionAnchor=anchor;descriptionScroll=main.scrollTop;dialog.classList.add('song-lyrics-dialog');$('#description-content').setAttribute('aria-label','Vollständiger Liedtext');$('#description-title').textContent=page.song.title||'';$('#description-subtitle').textContent=songSubtitle(page.song);$('#description-subtitle').hidden=!$('#description-subtitle').textContent;$('#description-text').textContent=page.lines.join('\n');dialog.showModal();main.scrollTop=descriptionScroll;$('#description-content').scrollTop=0;updateDescriptionFade();
}
function updateDescriptionFade(){const content=$('#description-content');$('#description-dialog').classList.toggle('description-at-end',content.scrollTop+content.clientHeight>=content.scrollHeight-1);}
$('#description-content').addEventListener('scroll',updateDescriptionFade,{passive:true});
new ResizeObserver(updateDescriptionFade).observe($('#description-content'));
$('#description-content').addEventListener('keydown',event=>{if(!['Home','End'].includes(event.key)||event.altKey||event.ctrlKey||event.metaKey)return;event.preventDefault();event.currentTarget.scrollTop=event.key==='End'?event.currentTarget.scrollHeight:0;updateDescriptionFade();});
$('#description-dialog').addEventListener('close',()=>{main.scrollTop=descriptionScroll;if(descriptionAnchor?.isConnected)descriptionAnchor.focus({preventScroll:true});});
$('#description-close').addEventListener('click',()=>$('#description-dialog').close());
$('#description-dialog').addEventListener('click',event=>{if(event.target!==event.currentTarget)return;const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.currentTarget.close();});
const compactAlbum=matchMedia('(max-width:999px)');
compactAlbum.addEventListener('change',applyPageTheme);
function openCollectionShare(anchor){
 const collection=state.collection;if(!collection)return;
 if(sharing.nativeAvailable){performMediaShare('share',collection.kind,collection);return;}
 const menu=contextMenuFor(anchor);menu.innerHTML=mediaShareButtons('data-share-choice');menu.hidden=false;menu.showPopover();positionContextMenu(menu,anchor);
 menu.onclick=event=>{const choice=event.target.closest('[data-share-choice]')?.dataset.shareChoice;if(!choice)return;menu.hidePopover();menu.hidden=true;if(anchor.isConnected)anchor.focus({preventScroll:true});performMediaShare(choice,collection.kind,collection);};menu.querySelector('button').focus({preventScroll:true});
}
function applyPageTheme(){
 document.body.classList.remove('themed');
 const image=main.querySelector('.detail-cover'),album=main.classList.contains('album-page'),playlist=main.classList.contains('playlist-page')&&!main.classList.contains('favorites-page');
 const clear=()=>{document.body.classList.remove('album-theme','album-light','playlist-theme');main.classList.remove('album-portrait','playlist-portrait');};
 if(!album&&!playlist){clear();return;}
 const generation=state.generation;
 const apply=()=>{
  if(generation!==state.generation||!image?.isConnected)return;
  const loaded=image.complete&&image.naturalWidth;
  if(playlist&&(!loaded||image.currentSrc.startsWith('data:'))){clear();return;}
  main.classList.toggle('album-portrait',album&&loaded&&image.naturalHeight>image.naturalWidth*1.15);
  main.classList.toggle('playlist-portrait',playlist&&loaded&&image.naturalHeight>image.naturalWidth*1.15);
  let tone={color:[86,86,91],light:false};
  try{if(loaded){const sample=document.createElement('canvas');sample.width=sample.height=32;const context=sample.getContext('2d',{willReadFrequently:true});context.drawImage(image,0,0,32,32);tone=albumCoverTone(context.getImageData(0,0,32,32).data);}}catch{if(playlist){clear();return;}}
  const palette=playlist?playlistPalette(tone):{sidebar:tone.color.map(channel=>Math.round(channel*.67))};
  document.body.style.setProperty('--album-color','rgb('+tone.color.join(' ')+')');
  document.body.style.setProperty('--album-sidebar','rgb('+palette.sidebar.join(' ')+')');
  if(playlist)document.body.style.setProperty('--playlist-secondary',palette.secondary);
  document.body.classList.add('album-theme');document.body.classList.toggle('playlist-theme',playlist);document.body.classList.toggle('album-light',tone.light);
 };
 apply();if(image&&!image.complete)image.addEventListener('load',apply,{once:true});
}
const artistPlaceholder="data:image/svg+xml,%3Csvg%20fill%3D%22%238a8a8e%22%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2228%22%20height%3D%2228%22%20viewBox%3D%220%200%2020%2022%22%20data-testid%3D%22library-general-artist-icon%22%20class%3D%22general-artist-icon%22%3E%3CclipPath%20id%3D%22a%22%3E%3Cpath%20d%3D%22m3%2016.2.7.8%208.6-8.4c-.2-.1-.3-.3-.5-.4-.2-.2-.3-.3-.4-.5zm8.9-13.6%205.6%205.6c-1.1%201-2.3%201.5-3.6%201.2l-2.7%202.5.1%202.5v6c0%20.7-.5%201.2-1.2%201.2s-1.2-.5-1.2-1.2v-6.2l-4.7%204.5c-.3.3-.8.3-1%200L1.5%2020c-.2.2-.6.2-.8-.1l-.3-.3c-.2-.3-.2-.6-.1-.8L1.4%2017c-.2-.2-.3-.7%200-1l9.2-9.8c-.2-1.3.2-2.6%201.3-3.6m1.3-1.3c1.7-1.7%203.9-1.7%205.6%200s1.6%203.9%200%205.6z%22%3E%3C%2Fpath%3E%3C%2FclipPath%3E%3Cpath%20d%3D%22M-5-5h30v31.6H-5z%22%20clip-path%3D%22url(%23a)%22%3E%3C%2Fpath%3E%3C%2Fsvg%3E";
function orderedArtists(){const compare=new Intl.Collator('de',{numeric:true,sensitivity:'base'}).compare;const artists=[...state.artists].sort((a,b)=>compare(a.name,b.name));return state.artistDescending?artists.reverse():artists;}
async function artistBrowser(id,generation){if(!state.artists.length){const data=await api('getArtists');if(generation!==state.generation)return '';state.artists=(data.artists?.index||[]).flatMap(x=>x.artist||[]);}const selected=id||state.selectedArtist||orderedArtists()[0]?.id;if(!selected)return empty('Noch keine Künstler');const data=await api('getArtist',{id:selected});if(generation!==state.generation)return '';const artist={...data.artist,id:data.artist?.id||selected};state.artistAlbums=[...(artist.album||[])].sort((a,b)=>(b.year||0)-(a.year||0)||String(a.name).localeCompare(String(b.name),'de'));state.selectedArtist=selected;state.artist=artist;return `<div class="artist-toolbar"><h1>Künstler</h1><button class="sort-trigger" data-artist-sort-menu aria-label="Künstler sortieren">${icon('sort')}${icon('down')}</button></div><div class="artist-browser"><div class="artist-list-pane"><div id="artist-list" role="listbox" aria-label="Künstler">${artistList(selected)}</div></div><article class="artist-library" aria-label="${esc(artist.name)}"><div class="artist-back"><button data-view="artists">${icon('artist-back')}<span>Künstler</span></button></div><div class="artist-library-heading"><h2>${esc(artist.name)}</h2><div><button data-artist-play ${state.artistAlbums.length?'':'disabled'} aria-label="Alle Titel von ${esc(artist.name)} wiedergeben">${icon('play')}</button><button data-artist-shuffle ${state.artistAlbums.length?'':'disabled'} aria-label="${esc(artist.name)} zufällig wiedergeben">${icon('shuffle')}</button>${favoriteButton(artist,'artist')}<button data-artist-menu aria-label="Aktionen für ${esc(artist.name)}">${icon('more')}</button></div></div>${state.artistAlbums.length?cards(state.artistAlbums,'album',false,true):empty('Keine Alben')}</article></div><footer class="artist-footer"><p>musik · Deine Mediathek</p><a href="/navidrome" target="_blank" rel="noreferrer">In Navidrome öffnen ↗</a></footer>`;}
function artistList(selected){return orderedArtists().map(a=>`<button class="artist-list-item ${a.id===selected?'active':''}" data-artist-id="${esc(a.id)}" data-open="artist/${encodeURIComponent(a.id)}" role="option" tabindex="${a.id===selected?'0':'-1'}" aria-selected="${a.id===selected}"><img src="${esc(a.coverArt?cover(a,80):artistPlaceholder)}" class="${a.coverArt?'':'artist-placeholder'}" alt="" loading="lazy"><span>${esc(a.name)}${state.favorites.artist.has(a.id)?`<span class="artist-star" aria-label="Favorit">${icon('favorite-selected')}</span>`:''}</span></button>`).join('');}
async function artistSongs(albums){const songs=[],ids=new Set();for(let offset=0;offset<albums.length;offset+=6){const results=await Promise.all(albums.slice(offset,offset+6).map(a=>api('getAlbum',{id:a.id})));for(const result of results)for(const song of result.album?.song||[])if(!ids.has(song.id)){ids.add(song.id);songs.push(song);}}return songs;}
let contextAnchor=null;
