main.addEventListener('keydown',e=>{const option=e.target.closest('.artist-list-item');if(!option||e.altKey||e.ctrlKey||e.metaKey)return;const list=orderedArtists(),index=list.findIndex(a=>a.id===option.dataset.artistId);let target;if(e.key==='ArrowDown')target=list[Math.min(index+1,list.length-1)];else if(e.key==='ArrowUp')target=list[Math.max(0,index-1)];else if(e.key==='Home')target=list[0];else if(e.key==='End')target=list.at(-1);else if(e.key.length===1&&e.key!==' '){artistTypeahead=Date.now()-artistTypeaheadAt<1000?artistTypeahead+e.key:e.key;artistTypeaheadAt=Date.now();const normalize=x=>x.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();target=list.find(a=>normalize(a.name).startsWith(normalize(artistTypeahead)));}if(target){e.preventDefault();state.artistKeyboardFocus=true;navigate('artist/'+encodeURIComponent(target.id));}});
