async function initialize(){const epoch=++state.accountEpoch,data=await fetch('/api/session').then(r=>r.json());if(epoch!==state.accountEpoch)return;for(const badge of document.querySelectorAll('.server-badge,#server-name'))badge.textContent=new URL(data.server).host;if(!data.authenticated){login.showModal();return;}state.user=data.user;recentSearches.setScope(data.server,data.user);libraryNavigation.setScope(data.server,data.user);navigationEditing=false;$('#username').textContent=data.user;$('#server-name').textContent=new URL(data.server).host;const [p,f]=await Promise.all([api('getPlaylists'),api('getStarred2')]);if(epoch!==state.accountEpoch)return;state.playlists=p.playlists?.playlist||[];for(const kind of ['song','album','artist'])state.favorites[kind]=new Set((f.starred2?.[kind]||[]).map(item=>item.id));await render();}
