function wireSearchShelves(root){
 searchShelfObserver?.disconnect();
 searchShelfObserver=new ResizeObserver(entries=>{for(const entry of entries)entry.target.dispatchEvent(new Event('scroll'));});
 for(const scroller of root.querySelectorAll('.search-songs,.search-albums .album-grid,.search-playlists .album-grid')){
  const frame=document.createElement('div');frame.className='search-shelf';scroller.before(frame);frame.append(scroller);
  frame.insertAdjacentHTML('afterbegin','<button class="search-page-arrow search-page-previous" type="button" aria-label="Vorherige Seite">'+searchShelfGlyph+'</button>');
  frame.insertAdjacentHTML('beforeend','<button class="search-page-arrow search-page-next" type="button" aria-label="Nächste Seite">'+searchShelfGlyph+'</button>');
  const previous=frame.querySelector('.search-page-previous'),next=frame.querySelector('.search-page-next');
  const update=()=>{const maximum=scroller.scrollWidth-scroller.clientWidth;previous.hidden=next.hidden=maximum<=1;previous.disabled=scroller.scrollLeft<=1;next.disabled=scroller.scrollLeft>=maximum-1;const art=scroller.querySelector('.cover-art');if(art)frame.style.setProperty('--search-arrow-y',art.getBoundingClientRect().height/2+'px');};
  const advance=direction=>{const item=scroller.firstElementChild;if(!item)return;const gap=parseFloat(getComputedStyle(scroller).columnGap)||0,stride=item.getBoundingClientRect().width+gap,columns=Math.max(1,Math.floor((scroller.clientWidth+gap+1)/stride));scroller.scrollBy({left:direction*columns*stride,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});};
  previous.onclick=()=>advance(-1);next.onclick=()=>advance(1);scroller.addEventListener('scroll',update,{passive:true});searchShelfObserver.observe(scroller);update();
 }
}
