 hydrate(target);updateTransport();selectSearchTab(searchTab,{record:false});wireSearchShelves(target);wireSearchArtists(target,result.artist||[]);
 target.querySelector('[data-search-all]')?.addEventListener('click',event=>{event.preventDefault();rememberSearchView();const term=target.dataset.searchTerm;history.pushState({...history.state,musikSearchDetail:{term,kind:'song'}},'',location.href);window.scrollTo(0,0);render();});
