  const holder=document.createElement('div');holder.innerHTML=searchSongTable(cache.items);hydrate(holder);main.querySelector('tbody').append(...Array.from(holder.querySelector('tbody').children).slice(start));tableSelection.sync(main.querySelector('table'));updateTransport();
