function syncPlayerMarquees(){for(const label of $$('.marquee-label')){if(!label.getClientRects().length||!label.clientWidth)continue;const text=label.querySelector('.marquee-text'),track=label.querySelector('.marquee-track');if(!text||!track)continue;const width=text.getBoundingClientRect().width,overflow=width>label.clientWidth+1;label.classList.toggle('is-overflowing',overflow);const gap=Number.parseFloat(getComputedStyle(label).getPropertyValue('--marquee-gap')),distance=width+(Number.isFinite(gap)?Math.max(0,gap):28);track.style.setProperty('--marquee-distance',distance+'px');track.style.setProperty('--marquee-duration',(distance/27)+'s');}}
