async function playAt(index){if(index<0||index>=state.queue.length)return;playback.select(index);const playGeneration=++state.playGeneration,song=current();scrobbleTracker.start(song);audio.src='/api/stream?id='+encodeURIComponent(song.id);$('#player').hidden=false;$('#player').classList.remove('idle');$('#mini-cover').hidden=false;$('#mini-cover').src=cover(song,100);$('#full-cover').src=cover(song,1000);setPlayerLabel('#mini-title',song.title,song);setPlayerLabel('#mini-artist',[song.artist,song.album].filter(Boolean).join(' — '));for(const id of ['#full-favorite','#mini-favorite']){$(id).dataset.favoriteId=song.id;$(id).dataset.favoriteTitle=song.title;}$('#mini-favorite').hidden=false;refreshFavorites();setPlayerLabel('#full-title',song.title,song);const metadata=playerMetadata(song);setPlayerLabel('#full-artist',metadata.text,null,metadata.html);$('#mini-seek').value=$('#full-seek').value=0;state.lyrics=null;lyricIndex=-2;renderLyrics();updateTransport();renderPanel();loadLyrics(song);try{await audio.play();}catch{if(playGeneration!==state.playGeneration)return;toast('Wiedergabe konnte nicht gestartet werden. Drücke noch einmal auf Play.');}if(playGeneration!==state.playGeneration)return;if('mediaSession'in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:song.title,artist:song.artist,album:song.album,artwork:[{src:new URL(cover(song,500),location.origin).href,sizes:'500x500'}]});}}
