function updateTransport(){document.body.classList.toggle('playback-running',!audio.paused);$('#player').classList.toggle('playing',!audio.paused);full.classList.toggle('playing',!audio.paused);$$('.transport button').forEach(b=>b.disabled=!current()&&state.queue.length===0);$$('.play-toggle').forEach(b=>{b.innerHTML=icon(audio.paused?'player-play':'player-pause');b.setAttribute('aria-label',audio.paused?'Wiedergabe':'Pause');});$$('[data-action="shuffle"]').forEach(b=>{b.classList.toggle('selected',state.shuffle);b.setAttribute('aria-pressed',String(state.shuffle));});$$('[data-action="repeat"]').forEach(b=>{b.classList.toggle('selected',state.repeat);b.setAttribute('aria-pressed',String(state.repeat>0));b.dataset.repeatMode=state.repeat;b.innerHTML=icon(state.repeat===2?'player-repeat-one':'player-repeat');b.setAttribute('aria-label',state.repeat===2?'Titel wiederholen':state.repeat===1?'Alle wiederholen':'Wiederholen');b.title=state.repeat===2?'Titel wiederholen':state.repeat===1?'Alle wiederholen':'Wiederholen';});$$('tr[data-song-id],.new-song[data-song-id],.search-song[data-song-id]').forEach(row=>{const selected=row.dataset.songId===current()?.id;row.classList.toggle('current',selected);row.classList.toggle('playing',selected&&!audio.paused);for(const slot of row.querySelectorAll('.song-art-play,.track-hover')){const key=selected?'current':'idle';if(slot.dataset.playbackState!==key){slot.innerHTML=selected?renderTrackPlayback(icon('play')):icon('play');slot.dataset.playbackState=key;}}});}
async function action(name,b){if(name==='toggle'){if(!current()){if(state.queue.length)playAt(0);return;}if(audio.paused){try{await audio.play();}catch{toast('Audio kann nicht wiedergegeben werden.');}}else audio.pause();}if(name==='previous'){if(audio.currentTime>3){scrobbleTracker.start(current());audio.currentTime=0;}else{const previous=state.index,index=playback.previous();if(index!==null){if(index===previous){scrobbleTracker.start(current());audio.currentTime=0;}else playAt(index);}}}if(name==='next')next();if(name==='shuffle'){state.shuffle=!state.shuffle;updateTransport();renderPanel();}if(name==='repeat'){state.repeat=(state.repeat+1)%3;updateTransport();}if(name==='fullscreen'&&current()){full.showModal();backdrop.resume();renderLyrics();renderFullQueue();requestAnimationFrame(syncPlayerMarquees);}if(name==='lyrics'||name==='queue'){if(state.panel===name)closePanel();else{state.panel=name;document.body.classList.add('has-panel');renderPanel();}}if(name==='mute'){$('.mini-volume').classList.add('is-open');audio.muted=!audio.muted;syncVolume();b?.focus({preventScroll:true});$('#mini-volume-range').focus({preventScroll:true});}if(name==='track-menu'&&current())openMenu(current(),b);}
