let playlistRemovalBusy=false;
async function removePlaylistEntries(selection){
 if(playlistRemovalBusy||!selection.indices.length)return;
 const epoch=state.accountEpoch,route='playlist/'+encodeURIComponent(selection.playlistId);playlistRemovalBusy=true;
 try{
  const response=await fetch('/api/playlist/remove',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(selection)}),result=await response.json();
  if(epoch!==state.accountEpoch)return;if(!response.ok)throw Error(result.error||'Titel konnten nicht entfernt werden.');
  await playlistActions.saved(result,selection.playlistId,false,'remove');if(epoch!==state.accountEpoch)return;
  toast(selection.indices.length===1?'Aus Playlist entfernt.':selection.indices.length+' Titel aus Playlist entfernt.');
  if(state.route===route){const rows=[...main.querySelectorAll('.song-table tbody tr')],row=rows[Math.min(selection.indices[0],rows.length-1)];if(row){tableSelection.state(row.closest('table')).select(Number(row.dataset.rowIndex));tableSelection.sync(row.closest('table'));row.focus({preventScroll:true});}else main.querySelector('[data-collection-menu]')?.focus({preventScroll:true});}
 }catch(error){if(epoch===state.accountEpoch)toast(error.message);}finally{playlistRemovalBusy=false;}
}
function openMenu(song,anchor,selectedSongs){
 const collection=state.collection,editable=anchor.closest('.song-table')&&collection?.kind==='playlist'&&state.route==='playlist/'+encodeURIComponent(collection.id)&&typeof collection.owner==='string'&&collection.owner.toLocaleLowerCase()===state.user?.toLocaleLowerCase();
 const removal=editable?{playlistId:collection.id,indices:tableSelection.indicesFor(anchor),expectedSongIds:state.viewSongs.map(item=>item.id)}:null;
 const songs=selectedSongs?.length?[...selectedSongs]:[song],multiple=songs.length>1,allFavorites=songs.every(item=>state.favorites.song.has(item.id)),epoch=state.accountEpoch;
 const menu=contextMenuFor(anchor);menu.innerHTML=`${removal?.indices.length?'<button role="menuitem" data-context="remove-playlist">'+icon('remove-playlist')+'Aus Playlist entfernen</button>':''}${playlistActionButton(false)}<button role="menuitem" data-context="next">${icon('collection-next')}Nächster Titel</button><button role="menuitem" data-context="last">${icon('collection-last')}Zuletzt wiedergeben</button><button role="menuitem" data-context="favorite">${icon('favorite')}${allFavorites?'Favoriten widerrufen':'Favorit:in'}</button>${!multiple?`<button role="menuitem" data-context="credits">${icon('credits')}Mitwirkende anzeigen</button>`:''}${!multiple?mediaShareButtons('data-context'):''}`;
 playlistActions.bind(menu,songs,anchor);menu.hidden=false;if(!menu.matches(':popover-open'))menu.showPopover();positionContextMenu(menu,anchor);menu.querySelector('button').focus({preventScroll:true});
 menu.onclick=async e=>{const b=e.target.closest('[data-context]');if(!b)return;const action=b.dataset.context;menu.hidePopover();menu.hidden=true;if(anchor.isConnected)anchor.focus({preventScroll:true});
  if(action==='remove-playlist'&&removal){await removePlaylistEntries(removal);return;}
  if(action==='favorite'){for(const id of new Set(songs.map(item=>item.id))){if(epoch!==state.accountEpoch)return;if(state.favorites.song.has(id)===allFavorites)await toggleFavorite(id,'song');}}
  if(action==='next'||action==='last'){playback.addMany(songs,{next:action==='next'});updateTransport();renderPanel();toast(action==='next'?'Wird als Nächstes wiedergegeben.':'Zur Warteschlange hinzugefügt.');}
  if(action==='link'||action==='share')performMediaShare(action,'song',song);
  if(action==='credits'){if(full.open)full.close();navigate('song/'+encodeURIComponent(song.id));}
 };
}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.mini-volume'))$('.mini-volume').classList.remove('is-open');if(!e.target.closest('.context-menu')&&!e.target.closest('[data-menu]')&&!e.target.closest('[data-collection-menu]')&&!e.target.closest('[data-action="track-menu"]')){$('#context').hidePopover();$('#context').hidden=true;}});
