function renderPlaybackPosition(seconds){const duration=Number.isFinite(audio.duration)?audio.duration:current()?.duration||0,elapsed=time(seconds),remaining='-'+time(Math.max(0,duration-seconds));for(const id of ['#elapsed','#mini-elapsed'])$(id).textContent=elapsed;for(const id of ['#remaining','#mini-remaining'])$(id).textContent=remaining;syncLyrics();}
const playerScrubber=new PlayerScrubber(audio,[$('#mini-seek'),$('#full-seek')],{format:time,enabled:()=>!!current(),tooltipFor:input=>input.id!=='mini-seek',preview:renderPlaybackPosition});
const storedVolume=Number(localStorage.getItem('musik-volume')??.5);audio.volume=Number.isFinite(storedVolume)?Math.max(0,Math.min(1,storedVolume)):.5;
function syncVolume(){const value=audio.muted?0:audio.volume;for(const input of [$('#volume'),$('#mini-volume-range')]){input.value=value;input.style.setProperty('--range-progress',value*100+'%');input.setAttribute('aria-valuetext',Math.round(value*100)+'%');}for(const b of $$('[data-action="mute"]'))b.setAttribute('aria-label',value===0?'Ton einschalten':'Ton aus');for(const svg of $$('.icon-volume'))for(let wave=1;wave<=3;wave++){const path=svg.querySelector('[data-testid="volume-wave-'+wave+'"]');if(path)path.style.opacity=value>(wave-1)/3?'1':'0';}}
for(const id of ['#volume','#mini-volume-range'])$(id).oninput=e=>{audio.muted=false;audio.volume=Number(e.target.value);localStorage.setItem('musik-volume',String(audio.volume));syncVolume();};audio.addEventListener('volumechange',syncVolume);syncVolume();
audio.addEventListener('timeupdate',()=>{scrobbleTracker.sample(audio.duration);if(!playerScrubber.active){playerScrubber.render(audio.currentTime);renderPlaybackPosition(audio.currentTime);}});audio.addEventListener('playing',()=>scrobbleTracker.resume());for(const event of ['pause','waiting','seeking'])audio.addEventListener(event,()=>scrobbleTracker.pause(audio.duration));audio.addEventListener('seeked',()=>{if(!audio.paused&&audio.readyState>=3)scrobbleTracker.resume();});audio.addEventListener('play',()=>{for(const target of [$('#full-lyrics'),$('#panel-lyrics')].filter(Boolean)){target.classList.remove('is-scrolling');lyricManualUntil.delete(target);clearTimeout(lyricManualTimers.get(target));}lyricIndex=-2;updateTransport();requestLyricFrame();});audio.addEventListener('pause',()=>{updateTransport();cancelAnimationFrame(lyricFrame);lyricFrame=0;});document.addEventListener('visibilitychange',()=>{cancelAnimationFrame(lyricFrame);lyricFrame=0;requestLyricFrame();});audio.addEventListener('ended',()=>{scrobbleTracker.finish(audio.duration);next(true);});audio.addEventListener('error',()=>{scrobbleTracker.pause(audio.duration);if(current())toast('Der Titel kann nicht abgespielt werden. Prüfe Verbindung oder Audioformat.');});
if('mediaSession'in navigator){navigator.mediaSession.setActionHandler('play',()=>audio.play().catch(()=>toast('Wiedergabe konnte nicht gestartet werden.')));navigator.mediaSession.setActionHandler('pause',()=>audio.pause());navigator.mediaSession.setActionHandler('previoustrack',()=>action('previous'));navigator.mediaSession.setActionHandler('nexttrack',()=>next());}
