const mobileFullPlayer=matchMedia('(max-width:999px)');
$('.mobile-collapse').innerHTML=mobilePlayerIcons.collapse;$('.mobile-volume-min').innerHTML=mobilePlayerIcons.volume[0];$('.mobile-volume-max').innerHTML=mobilePlayerIcons.volume[1];
function syncFullModes(){const lyrics=!full.classList.contains('lyrics-hidden'),queue=full.classList.contains('queue-visible');const lyricsButton=$('.full-lyrics-toggle'),queueButton=$('.full-queue-toggle');lyricsButton.setAttribute('aria-label',lyrics?'Liedtext ausblenden':'Liedtext einblenden');lyricsButton.setAttribute('aria-pressed',String(lyrics));queueButton.setAttribute('aria-pressed',String(queue));lyricsButton.innerHTML=mobileFullPlayer.matches?mobilePlayerIcons[lyrics?'lyricsOn':'lyricsOff']:icon('lyrics');queueButton.innerHTML=mobilePlayerIcons[queue?'queueOn':'queueOff'];$('#full-queue').hidden=!queue||!mobileFullPlayer.matches;}
function setFullView(view){full.classList.toggle('lyrics-hidden',view!=='lyrics');full.classList.toggle('queue-visible',view==='queue');syncFullModes();renderFullQueue();requestAnimationFrame(()=>{lyricIndex=-2;syncLyrics();syncPlayerMarquees();});}
function syncFullPlayerLayout(){if(mobileFullPlayer.matches&&state.panel)closePanel();const target=mobileFullPlayer.matches?$('.full-main'):$('.full-layout'),modes=$('.full-modes');for(const node of [$('#full-lyrics'),$('#full-queue')]){if(mobileFullPlayer.matches)target.append(node);else target.insertBefore(node,modes);}$('.full-cover-action').tabIndex=mobileFullPlayer.matches?0:-1;if(!mobileFullPlayer.matches&&full.classList.contains('queue-visible'))setFullView('lyrics');syncFullModes();requestAnimationFrame(()=>{lyricIndex=-2;syncLyrics();syncPlayerMarquees();});}
$('.full-lyrics-toggle').onclick=()=>setFullView(full.classList.contains('lyrics-hidden')?'lyrics':'cover');$('.full-queue-toggle').onclick=()=>setFullView(full.classList.contains('queue-visible')?'cover':'queue');$('.full-cover-action').onclick=()=>{if(mobileFullPlayer.matches)setFullView('cover');};mobileFullPlayer.addEventListener('change',syncFullPlayerLayout);syncFullPlayerLayout();
$('#full-cover').addEventListener('load',()=>backdrop.setCover($('#full-cover')));
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render();});setMobileNavigation(false);hydrate();updateTransport();syncVolume();initialize().catch(e=>toast(e.message));
